"""Writes src/shared/Assets/PerkMaps.luau from build/perk_maps/perk_maps.json and the uploaded atlas ids.

    .venv/Scripts/python.exe tools/assets/write_perk_maps.py <atlas_0 id> <atlas_1 id> ...
"""

import json
import os
import sys

REPO = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
m = json.load(open(os.path.join(REPO, "build", "perk_maps", "perk_maps.json")))
ids = sys.argv[1:]
lines = [
    "-- GENERATED by tools/assets/write_perk_maps.py (frames from tools/assets/make_perk_maps.py).",
    "-- The shop's live maps: per plague perk, 8 frames of a real piece of the world with the infection",
    "-- moving (ImageRectOffset into an atlas), and the points its scene needs (fractions of a frame).",
    "return {",
    "\tframe = Vector2.new(%d, %d)," % tuple(m["frame"]),
    "\tatlases = { %s }," % ", ".join('"rbxassetid://%s"' % i for i in ids),
    "\tscenes = {",
]
for name, sc in m["scenes"].items():
    frames = ", ".join("{ %d, %d, %d }" % (a + 1, x, y) for a, x, y in sc["frames"])
    pts = ", ".join("%s = Vector2.new(%s, %s)" % (k, v[0], v[1]) for k, v in sc["points"].items())
    lines.append("\t\t%s = { frames = { %s }, points = { %s } }," % (name, frames, pts))
lines += ["\t},", "}", ""]
open(os.path.join(REPO, "src", "shared", "Assets", "PerkMaps.luau"), "w", encoding="utf-8", newline="\n").write("\n".join(lines))
print("ok")
